&lt;p&gt;&lt;a&gt;&lt;img src= &#34;https://fs.weidows.tech/img/img/loading.svg&#34; data-lazy-src=&#34;https://fs.weidows.tech/img/img/divider.png&#34; alt=&#34;分割线&#34;&gt;&lt;/a&gt;&lt;/p&gt;
&lt;h2 id=&#34;theme&#34;&gt;theme&lt;/h2&gt;
&lt;p&gt;自己写的一个主题, 感觉挺好用的 (只是启动时稍慢一些)&lt;/p&gt;
&lt;p&gt;&lt;img src= &#34;https://fs.weidows.tech/img/img/loading.svg&#34; data-lazy-src=&#34;https://fs.weidows.tech/img/blog/2026-08/1787551436049.jpeg&#34; alt=&#34;1787551435977.png&#34;&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight pwsh&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置主题 | https://ohmyposh.dev/docs/themes&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 网不好时可能不会生效&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;oh&lt;/span&gt;&lt;span class=&#34;literal&#34;&gt;-my-posh&lt;/span&gt; init pwsh &lt;span class=&#34;literal&#34;&gt;--config&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;https://cdn.jsdelivr.net/gh/Weidows-projects/Programming-Configuration@master/others/pwsh/weidows.omp.json&amp;quot;&lt;/span&gt; | &lt;span class=&#34;built_in&#34;&gt;Invoke-Expression&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;&lt;a&gt;&lt;img src= &#34;https://fs.weidows.tech/img/img/loading.svg&#34; data-lazy-src=&#34;https://fs.weidows.tech/img/img/divider.png&#34; alt=&#34;分割线&#34;&gt;&lt;/a&gt;&lt;/p&gt;
&lt;h2 id=&#34;借物表&#34;&gt;借物表&lt;/h2&gt;
&lt;p&gt;暂无.&lt;/p&gt;
&lt;script type=&#34;text&amp;#x2F;javascript&#34; src=&#34;https://unpkg.com/kity@2.0.4/dist/kity.min.js&#34;&gt;&lt;/script&gt;&lt;script type=&#34;text&amp;#x2F;javascript&#34; src=&#34;https://unpkg.com/kityminder-core@1.4.50/dist/kityminder.core.min.js&#34;&gt;&lt;/script&gt;&lt;script type=&#34;text&amp;#x2F;javascript&#34; src=&#34;/mindmap/mindmap.js&#34;&gt;&lt;/script&gt;&lt;link rel=&#34;stylesheet&#34; type=&#34;text&amp;#x2F;css&#34; href=&#34;/mindmap/mindmap.css&#34;&gt;
